# Initially generated by GitHub Copilot.
"""Load the precomputed tmpl-survey artifacts for the plus and plain corpora."""

import json
import os

_PATH = "out/MAM-tmpl-survey/plus.json"
_PLAIN_PATH = "out/MAM-tmpl-survey/plain.json"
_REGEN_MSG = "    .venv\\Scripts\\python.exe py\\main_tmpl_survey.py"


def load() -> dict:
    """Load out/MAM-tmpl-survey/plus.json. Caller must run from repo root.

    Raises FileNotFoundError with an instructive message if absent. Does NOT
    regenerate; that is intentionally a manual step (`py\\main_tmpl_survey.py`).
    """
    if not os.path.exists(_PATH):
        raise FileNotFoundError(
            f"{_PATH} not found. Generate it first with:\n{_REGEN_MSG}"
        )
    with open(_PATH, encoding="utf-8") as fh:
        return json.load(fh)


def load_plain() -> dict:
    """Load out/MAM-tmpl-survey/plain.json. Same guarantees as load()."""
    if not os.path.exists(_PLAIN_PATH):
        raise FileNotFoundError(
            f"{_PLAIN_PATH} not found. Generate it first with:\n{_REGEN_MSG}"
        )
    with open(_PLAIN_PATH, encoding="utf-8") as fh:
        return json.load(fh)


def template_names_observed(survey: dict) -> set[str]:
    """Set of all wtel_subtype values that appear in column_counts.

    For special-kq templates this is the unified template name, NOT the
    per-סוג= subtype string.
    """
    return {row["wtel_subtype"] for row in survey["column_counts"]}


def arg_counts_for(survey: dict, tmpl_name: str) -> set[int]:
    """Set of distinct arg_count values observed for the given template."""
    return {
        row["arg_count"]
        for row in survey["arg_counts"]
        if row["wtel_subtype"] == tmpl_name
    }


def template_names_observed_both(survey_plus: dict, survey_plain: dict) -> set[str]:
    """Union of template names observed in the plus and plain surveys.

    Use this for mp.both.* claims. Some templates exist only in the plain
    corpus because mpplus_boring_tmpls.py expands them to inline text before
    writing the plus JSON, so they never appear in the plus survey alone.
    """
    return template_names_observed(survey_plus) | template_names_observed(survey_plain)
